-- +goose Up
-- The client's iron list (2026-11-20, an Excel file). The producer matters everywhere (client: «میلگرد 16 ذوب آهن» and
-- «میلگرد 16 میانه» are different products), so every row is its own product, named as in the file (spaces tidied,
-- Arabic ي/ك as Persian ی/ک):
--   * raw materials in «بازار»: گندله, سنگ آهن و کنسانتره, آهن اسفنجی, per producer;
--   * intermediate products in «بازار» in eleven groups (ورق سیاه، ورق روغنی، ورق رنگی، میلگرد آجدار، میلگرد ساده، میلگرد
--     آلیاژی، تیرآهن، لوله درزدار، نبشی، ناودانی، تسمه نوردی); rows the file repeats word for word are added once;
--   * the IME, a month of trades (1405-08-02 to 08-27): one product per traded symbol (grade and producer), «name
--     (producer)», in seven groups (شمش بلوم، تختال، ورق، میلگرد، تیرآهن، نبشی، ناودانی) for the ticker's averages.
-- Additive only (ON CONFLICT DO NOTHING); a row appears on the site once it has a price. Nothing happens on a fresh
-- database.
INSERT INTO market.product_groups (metal_id, category_id, name_fa, name_en, sort)
SELECT m.id, c.id, g.name_fa, g.name_en, g.sort
FROM market.metals m,
     (VALUES
       ('raw', 'گندله', 'Iron ore pellets', 1),
       ('raw', 'سنگ آهن و کنسانتره', 'Iron ore and concentrate', 2),
       ('raw', 'آهن اسفنجی', 'Sponge iron (DRI)', 3),
       ('intermediate', 'ورق سیاه', 'Hot-rolled plate', 4),
       ('intermediate', 'ورق روغنی', 'Cold-rolled sheet', 5),
       ('intermediate', 'ورق رنگی', 'Pre-painted sheet', 6),
       ('intermediate', 'میلگرد آجدار', 'Ribbed rebar', 7),
       ('intermediate', 'میلگرد ساده (بدون آج)', 'Plain bar', 8),
       ('intermediate', 'میلگرد آلیاژی', 'Alloy bar (shaft)', 9),
       ('intermediate', 'تیرآهن', 'Steel beam', 10),
       ('intermediate', 'لوله درزدار', 'Welded pipe', 11),
       ('intermediate', 'نبشی', 'Angle', 12),
       ('intermediate', 'ناودانی', 'Channel', 13),
       ('intermediate', 'تسمه نوردی', 'Flat bar', 14),
       ('intermediate', 'شمش بلوم بورس کالا', 'IME bloom', 15),
       ('intermediate', 'تختال بورس کالا', 'IME slab', 16),
       ('intermediate', 'ورق بورس کالا', 'IME sheet', 17),
       ('intermediate', 'میلگرد بورس کالا', 'IME rebar', 18),
       ('intermediate', 'تیرآهن بورس کالا', 'IME beam', 19),
       ('intermediate', 'نبشی بورس کالا', 'IME angle', 20),
       ('intermediate', 'ناودانی بورس کالا', 'IME channel', 21)) AS g (category, name_fa, name_en, sort)
JOIN market.product_categories c ON c.slug = g.category
WHERE m.slug = 'iron'
ON CONFLICT (metal_id, category_id, name_fa) DO NOTHING;

