  ('iron-ime-sst-mreeeea3b-00', 'میلگرد 14تا20-A3 (فولاد صنعت صائب تبریز)', 'intermediate', 'میلگرد بورس کالا', 'ime', true, 666),
  ('iron-ime-dota-hreenna3b-00', 'میلگرد 22 و 25 (گروه صنعتی درپاد تبریز (کارخانجات گروه صنعتی درپاد تبریز))', 'intermediate', 'میلگرد بورس کالا', 'ime', true, 667),
